SELECT a,b,c FROM (SELECT 1 AS a,'a' AS b,'a' AS c UNION ALL SELECT 9.9,'b','B' UNION ALL SELECT NULL,'C','c' UNION ALL SELECT 'hello','d','D' UNION ALL SELECT x'616263','e','e') UNION ALL SELECT x,y,z FROM (SELECT NULL AS x,'U' AS y,'u' AS z UNION ALL SELECT 'mad','Z','z' UNION ALL SELECT x'68617265','m','M' UNION ALL SELECT 5.2e6,'X','x' UNION ALL SELECT -23,'Y','y') ORDER BY a,b,c;